$scenario('deadline_stops_claims',function()use($pdo,$reset,$assert,$job){$reset();$r=new QueueCoreRepository($pdo);$r->enqueue($job(1,'normal','deadline'));$registry=new QueueHandlerRegistry();$registry->register('test_work',new class implements QueueHandler{public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{return QueueResult::completed();}});$s=(new QueueRunner($r,$registry))->run(new QueueRunRequest('test','w',10,microtime(true)-1));$assert($s['claimed']===0&&$s['reason']==='deadline');});
